(()=>{
 const opener=document.getElementById('ion-pack-preview');if(!opener)return;
 const dialog=document.createElement('dialog');dialog.setAttribute('aria-label','Ion collection purchase');dialog.className='ion-pack-dialog';document.body.append(dialog);
 let pending=null,busy=false;
 const el=(tag,text)=>{const n=document.createElement(tag);n.textContent=text;return n;};
 async function request(path,body){const session=await window.EarnlyCloud?.session?.();if(!session)throw Error('Sign in to preview your bundle price.');if(pending&&pending.owner!==session.user.id){pending=null;throw Error('Your account changed. Preview this pack again.');}const response=await fetch(window.EARNLY_AVATAR_API+'/api/'+path,{method:body?'POST':'GET',headers:{Authorization:'Bearer '+session.access_token,'Content-Type':'application/json',...(pending?{'Idempotency-Key':pending.key}:{})},body:body?JSON.stringify(body):undefined,cache:'no-store'});const data=await response.json();if(!response.ok)throw Error(data.error?.message||'Could not complete this request.');return data;}
 opener.onclick=async()=>{if(busy)return;busy=true;try{const session=await window.EarnlyCloud?.session?.();if(!session){document.getElementById('auth-modal').showModal();return;}pending=null;const quote=await request('ion-pack');pending={key:crypto.randomUUID(),owner:session.user.id,price:quote.price};dialog.replaceChildren();dialog.append(el('h2','Ion collection'),el('p','Army colors, commander style, building colors and battle effects. Cosmetics only.'));
 const art=el('div','');art.className='ion-pack-art';for(const part of ['army','commander','building','battlefx']){const img=document.createElement('img');img.src='cosmetic-ion-'+part+'.svg';img.alt='Ion '+part;art.append(img);}dialog.append(art,el('p',quote.price+' Arcade Coins · '+quote.remaining+' new items. Owned pieces are excluded.'));
 const status=el('p','');status.setAttribute('role','status');const buy=el('button','Confirm · '+quote.price+' coins');buy.disabled=quote.remaining===0;const cancel=el('button','Cancel');cancel.onclick=()=>dialog.close();
 buy.onclick=async()=>{if(busy)return;busy=true;buy.disabled=true;cancel.disabled=true;try{await request('shop/ion-pack',{expectedPrice:pending.price});pending=null;document.getElementById('refresh-button').click();status.textContent='Ion collection owned and equipped.';}catch(error){status.textContent=error.message;buy.disabled=false;}finally{busy=false;cancel.disabled=false;}};
 dialog.append(status,buy,cancel);dialog.showModal();}catch(error){document.getElementById('status').textContent=error.message;}finally{busy=false;}};
})();
